package com.ecommerce.commerceapi.inventory.repository; import com.ecommerce.commerceapi.inventory.domain.InventoryTransaction; import org.springframework.data.jpa.repository.*; import java.util.*; public interface InventoryTransactionRepository extends JpaRepository<InventoryTransaction,Long>{ @Query("select coalesce(sum(case when t.transactionType in ('OPENING_STOCK','PURCHASE','MANUFACTURED','RETURN','ADJUSTMENT_IN') then t.quantity else -t.quantity end),0) from InventoryTransaction t where t.variant.id=:variantId") int balance(Long variantId); List<InventoryTransaction> findByVariantIdOrderByTransactionDateDesc(Long variantId); }
